INSERT INTO questions (question_text, correct_letter, explanation, trait) VALUES ('General Ishii Shiros name is often connected with his experiments with germs and bio-weapons. Which one of the following is the correct name of the headquarters of the Japanese Biological Warfare Unit 731 during World War II?', 'C', 'Pingfan', 'WALL_OF_TEXT');
