INSERT INTO questions (question_text, correct_letter, explanation, trait) VALUES ('Valentina Tereshkova was the first woman to fly in space. Her mission took place on June 16, 1963. How long was her flight?', 'D', '2 days, 22 hours, 50 minutes', 'STANDARD');
