INSERT INTO questions (question_text, correct_letter, explanation, trait) VALUES ('Pas dArmes was a tournament, in which knights were dared to fight.  If knights refused to fight, they had to leave this behind as a sign of humiliation.', 'A', 'Spurs', 'STANDARD');
